import type { GetServerSideProps } from "next";

type Props = { name: string };

export const getServerSideProps: GetServerSideProps<Props> = async (context) => {
  const res = await fetch(`${process.env.API_URL}/products/${context.params?.slug}`);
  if (res.status === 404) return { notFound: true };
  const product = await res.json();
  return { props: { name: product.name } };
};

export default function ProductPage({ name }: Props) {
  return <h1>{name}</h1>;
}

import { notFound } from "next/navigation";

export default async function ProductPage({ params }: PageProps<"/products/[slug]">) {
  const { slug } = await params;
  const res = await fetch(`${process.env.API_URL}/products/${slug}`);
  if (res.status === 404) notFound();
  const product = await res.json();

  return <h1>{product.name}</h1>;
}

